<original_code>
#include <bits/stdc++.h>
using namespace std;

const int N = 1000005;
const int MOD = 1000000007;

int a[N];
bool visited[N];
int p_value, k_value;

int main()
{
    cin >> p_value >> k_value;
    if (k_value == 0) {
        long long result = 1;
        for (int i = 1; i < p_value; ++i) {
            result = (result * p_value) % MOD;
        }
        cout << result << "\n";
        return 0;
    }
    for (int i = 1; i < p_value; ++i) {
        a[i] = (long long)k_value * i % p_value;
    }
    long long answer = 1;
    for (int i = 0; i < p_value; ++i) {
        if (!visited[i]) {
            int cycle_size = 0;
            int j = i;
            int tmp_product = 1;
            while (!visited[j]) {
                visited[j] = true;
                j = a[j];
                cycle_size++;
                tmp_product = (long long)tmp_product * k_value % p_value;
            }
            if (cycle_size == 1) {
                int count = (k_value == 1) ? p_value : 1;
                answer = (answer * count) % MOD;
            } else {
                assert(tmp_product == 1);
                answer = (answer * p_value) % MOD;
            }
        }
    }
    cout << answer << "\n";
}
